local function tokenize(s)
  local t = {}
  local i = 1
  local n = #s
  while i <= n do
    local c = s:sub(i, i)
    if c == "<" then
      local j = s:find("<", i + 1, true)
      local seg = s:sub(i + 1, (j or n + 1) - 1)
      t[#t + 1] = { cmd = seg }
      i = j or n + 1
    else
      local j = s:find("<", i, true)
      t[#t + 1] = { text = s:sub(i, (j or n + 1) - 1) }
      i = j or n + 1
    end
  end
  return t
end

function scr_run(ev)
  local st = SCRIPTS[G.stage]
  local text = st and st[ev]
  if not text then
    scr.active = false
    scr.lock = false
    return
  end
  scr.active = true
  scr.lock = true
  scr.toks = tokenize(text)
  scr.pc = 1
  scr.wait = 0
  scr.wait_key = false
  scr.msg = nil
  scr.pend = nil
end

function scr_stop()
  scr.active = false
  scr.lock = false
  scr.msg = nil
  scr.pend = nil
  scr.fade_cb = nil
end

-- 排版：把文本按 \n 分行、按每页 3 行分页
local function msg_push(str)
  local m = scr.msg
  for line in str:gmatch("([^\n]*)\n?") do
    if #m.lines < 3 then
      m.lines[#m.lines + 1] = line
    else
      m.overflow = (m.overflow or "") .. line .. "\n"
    end
  end
end

local function msg_open()
  scr.msg = { lines = {}, chars = 0, blink = 0 }
end

-- 令牌参数解析：原版 TSC 为十进制定宽数字，冒号分隔
local function args(s)
  local r = {}
  for v in s:gmatch("[^:]+") do
    r[#r + 1] = tonumber(v) or 0
  end
  return r
end

local function exec(tok)
  local c = tok.cmd
  local op = c:sub(1, 3)
  local rest = c:sub(4)
  if tok.text then
    if scr.msg then msg_push(tok.text:gsub("\r", "")) end
    return true
  end
  if op == "MSG" then
    msg_open()
    local tail = rest
    if tail ~= "" then msg_push(tail) end
  elseif op == "NOD" then
    if scr.msg and (scr.msg.overflow or "") ~= "" then
      scr.msg.lines = {}
      local ov = scr.msg.overflow
      scr.msg.overflow = nil
      msg_push(ov)
    end
    if scr.msg then scr.msg.chars = msg_total(scr.msg) end
    scr.wait_key = true
    sfx(SFX.blip)
    return false
  elseif op == "CLR" then
    if scr.msg then scr.msg.lines = {} end
  elseif op == "CLO" then
    scr.msg = nil
  elseif op == "KEY" then
    -- 无操作：不阻塞（文本框由 NOD/END 控制）
  elseif op == "PRI" then
    scr.lock = true
  elseif op == "END" then
    scr_stop()
    return false
  elseif op == "EVE" then
    local a = args(rest)
    scr_stop()
    scr_run(a[1])
    return false
  elseif op == "WAI" then
    scr.wait = tonumber(rest) or 0
    return false
  elseif op == "TRA" then
    local a = args(rest)
    scr.trans = { stage = a[1], ev = a[2], tx = a[3], ty = a[4] }
    return false
  elseif op == "FL+" then
    flset(tonumber(rest) or 0)
  elseif op == "FL-" then
    flclr(tonumber(rest) or 0)
  elseif op == "FLJ" then
    local a = args(rest)
    if flget(a[1]) then
      scr_stop()
      scr_run(a[2])
      return false
    end
  elseif op == "IT+" then
    local a = args(rest)
    G.items[a[1]] = true
  elseif op == "ITJ" then
    local a = args(rest)
    if G.items[a[1]] then
      scr_stop()
      scr_run(a[2])
      return false
    end
  elseif op == "AM+" then
    local a = args(rest)
    give_weapon(a[1], (a[2] or 0) + 1)
  elseif op == "AMJ" then
    local a = args(rest)
    if G.weapon and G.weapon.id == a[1] then
      scr_stop()
      scr_run(a[2])
      return false
    end
  elseif op == "SOU" then
    sfx(tonumber(rest) or 0)
  elseif op == "CNP" then
    local a = args(rest)
    npc_change_event(a[1], a[2])
  elseif op == "DNP" then
    local a = args(rest)
    npc_delete_event(a[1])
  elseif op == "TUR" then
    -- 玩家面向最近的 interactable：简化为不动
  elseif op == "SKJ" then
    local a = args(rest)
    if flget(a[1]) then
      scr_stop()
      scr_run(a[2])
      return false
    end
  else
    -- <CMU <MYD <RMU <ANP <HMC <SMC <GIT <FAI <FAO <WAI 以外的原版指令一律忽略
  end
  return true
end

function scr_update()
  if scr.msg and not scr.wait_key then
    -- 打字机：每帧 2 字符
    scr.msg.chars = math.min(scr.msg.chars + 2, msg_total(scr.msg))
  end
  if scr.trans then
    -- 等淡出完成（由 game 层驱动 fade，之后执行转场）
    G.fade_tgt = 4
    if G.fade >= 4 then
      local t = scr.trans
      scr.trans = nil
      stage_switch(t.stage, t.ev, t.tx, t.ty)
    end
    return
  end
  if not scr.active then return end
  if scr.wait > 0 then
    scr.wait = scr.wait - 1
    return
  end
  if scr.wait_key then
    if btnp("a") or btnp("b") or btnp("x") or btnp("y") then
      scr.wait_key = false
    end
    return
  end
  while scr.pc <= #scr.toks do
    local tok = scr.toks[scr.pc]
    scr.pc = scr.pc + 1
    if not exec(tok) then
      return
    end
    if scr.wait > 0 or scr.wait_key then
      return
    end
  end
  -- 令牌耗尽：结束
  scr_stop()
end

-- 事件是否需要玩家硬锁定（对话、门、演出）
function scr_locks_player()
  return scr.active or scr.trans ~= nil
end

-- ════════ 30_player.lua ════════
-- 30_player.lua —— 玩家（库特）：移动、跳跃、射击、受击、动画

plr = nil

function new_player(tx, ty, dir)
  return {
    x = (tx * 16 + 8) * SUB,
    y = (ty * 16 + 8) * SUB,
    vx = 0, vy = 0,
    dir = dir or 1,            -- -1 左 / 1 右
    up = false, down = false,
    on_ground = false,
    life = 3, max_life = 3,
    shock = 0,                 -- 受击无敌帧
    anim = 0,                  -- 行走动画计数
    xp_timer = 0,
    weapon = nil,              -- {id=2, level=1..3, exp=0}
  }
end

function give_weapon(id, level)
  if plr.weapon and plr.weapon.id == id then return end
  plr.weapon = { id = id, level = level or 1, exp = 0 }
  sfx(SFX.levelup)
  caret_spawn(plr.x, plr.y - 10 * SUB, "level", 0)
end

local function add_xp(n)
  local w = plr.weapon
  if not w then return end
  w.exp = w.exp + n
  local lt = WEAPON.level_table
  if w.level < 3 and w.exp >= lt[w.level] then
    w.level = w.level + 1
    w.exp = 0
    sfx(SFX.levelup)
    caret_spawn(plr.x, plr.y - 10 * SUB, "level", 0)
  elseif w.level >= 3 then
    w.exp = 0
  end
  plr.xp_timer = 30
end

function plr_damage(dmg)
  if plr.shock > 0 or plr.life <= 0 then return end
  sfx(SFX.hurt)
  plr.shock = 128
  plr.vy = -0x400
  plr.life = plr.life - dmg
  if plr.life <= 0 then
    plr.life = 0
    G.dead_t = 100
    sfx(SFX.die)
    for i = 1, 24 do
      npc_spawn_smoke(plr.x + math.floor(rnd(-10, 10)) * SUB, plr.y + math.floor(rnd(-10, 10)) * SUB)
    end
  end
end

-- ─── 地图碰撞 ───────────────────────────────────────────────

local function cell_solid(cx, cy)
  local t = mget(cx, cy)
  return fget(t, 0)
end

-- 移动后的探针检测：横向
local function collide_x(e, l, r, t, b)
  if e.vx > 0 then
    local cx = sar(e.x + r, 13)
    local rows = { sar(e.y - t + 256, 13), sar(e.y + b - 256, 13) }
    for i = 1, 2 do
      if cell_solid(cx, rows[i]) then
        e.x = lsl(cx, 13) - r
        e.vx = 0
        return
      end
    end
  elseif e.vx < 0 then
    local cx = sar(e.x - l, 13)
    local rows = { sar(e.y - t + 256, 13), sar(e.y + b - 256, 13) }
    for i = 1, 2 do
      if cell_solid(cx, rows[i]) then
        e.x = lsl(cx + 1, 13) + l
        e.vx = 0
        return
      end
    end
  end
end

local function collide_y(e, l, r, t, b)
  e.on_ground = false
  if e.vy > 0 then
    local cy = sar(e.y + b, 13)
    local cols = { sar(e.x - l + 256, 13), sar(e.x + r - 256, 13) }
    for i = 1, 2 do
      if cell_solid(cols[i], cy) then
        e.y = lsl(cy, 13) - b
        e.vy = 0
        e.on_ground = true
        return
      end
    end
  elseif e.vy < 0 then
    local cy = sar(e.y - t, 13)
    local cols = { sar(e.x - l + 256, 13), sar(e.x + r - 256, 13) }
    for i = 1, 2 do
      if cell_solid(cols[i], cy) then
        e.y = lsl(cy + 1, 13) + t
        e.vy = 0
        return
      end
    end
  end
end

-- 斜坡（sflags bit1..3 = 坡码 1..8；几何取自原版 test_hit_*_slope_*）
local function slope_at(e, l, r, t, b)
  local cx = sar(e.x, 13)
  local cy = sar(e.y + b, 13)
  local t0 = mget(cx, cy)
  local code = bit32.bor(fget(t0, 1) and 1 or 0, fget(t0, 2) and 2 or 0, fget(t0, 3) and 4 or 0)
  if code == 0 then return end
  local dx = e.x - lsl(cx, 13)
  local ty0 = lsl(cy, 13)
  local Q = 0x800
  local line
  if code == 5 then line = ty0 + dx // 2 - Q        -- 0x54 左升(整高)
  elseif code == 6 then line = ty0 + dx // 2 + Q    -- 0x55 左升(半高)
  elseif code == 7 then line = ty0 - dx // 2 + Q    -- 0x56 右升(半高)
  elseif code == 8 then line = ty0 - dx // 2 - Q    -- 0x57 右升(整高)
  end
  if line and e.y + b > line then
    e.y = line - b
    if e.vy > 0 then e.vy = 0 end
    e.on_ground = true
  end
end

-- 天花板斜坡（坡码 1..4）
local function ceil_slope(e, l, r, t, b)
  local cx = sar(e.x, 13)
  local cy = sar(e.y - t, 13)
  local t0 = mget(cx, cy)
  local code = bit32.bor(fget(t0, 1) and 1 or 0, fget(t0, 2) and 2 or 0, fget(t0, 3) and 4 or 0)
  if code == 0 or code > 4 then return end
  local dx = e.x - lsl(cx, 13)
  local ty0 = lsl(cy, 13)
  local Q = 0x800
  local line
  if code == 1 then line = ty0 - dx // 2 + Q
  elseif code == 2 then line = ty0 - dx // 2 - Q
  elseif code == 3 then line = ty0 + dx // 2 - Q
  elseif code == 4 then line = ty0 + dx // 2 + Q
  end
  if line and e.y - t < line then
    e.y = line + t
    if e.vy < 0 then e.vy = 0 end
  end
end

-- ─── 射击 ─────────────────────────────────────────────────

local function shoot()
  local w = plr.weapon
  if not w then return end
  if bullet_count_player() >= WEAPON.max_on_screen then return end
  local lvl = w.level
  local mx, my, dir
  if plr.up then
    mx = plr.dir * SUB
    my = -0x1000
    dir = "up"
  elseif plr.down and not plr.on_ground then
    mx = plr.dir * SUB
    my = 0x1000
    dir = "down"
  else
    mx = plr.dir * 0xc00
    my = 0x600
    dir = plr.dir < 0 and "left" or "right"
  end
  bullet_spawn(plr.x + mx, plr.y + my, dir, lvl)
  caret_spawn(plr.x + mx * 2, plr.y + my, "shoot", plr.dir)
  if lvl >= 3 then sfx(SFX.shoot3) else sfx(SFX.shoot) end
end

-- ─── 交互（↑ 键触发）───────────────────────────────────────

local function try_interact()
  local px0, py0 = plr.x - 28 * SUB, plr.y - 30 * SUB
  local px1, py1 = plr.x + 28 * SUB, plr.y + 30 * SUB
  local best, bd = nil, bit32.lshift(1, 30)
  local cand_n = 0
  for i = 1, #npcs do
    local n = npcs[i]
    if n.ev > 0 or n.t == 16 or n.t == 39 or n.t == 17 then
      cand_n = cand_n + 1
      local st = CS.stats[n.t]
      local dp = st and st.dp
      if dp then
        local x0, y0 = n.x - dp[1] * SUB, n.y - dp[2] * SUB
        local x1, y1 = n.x + dp[3] * SUB, n.y + dp[4] * SUB
        if x0 < px1 and x1 > px0 and y0 < py1 and y1 > py0 then
          local d = math.abs(n.x - plr.x) + math.abs(n.y - plr.y)
          if d < bd then best, bd = n, d end
        end
      end
    end
  end
  if best then
    G.interact_cd = 30
    G.interact_latch = true
    plr.dir = best.x >= plr.x and 1 or -1
    if best.t == 16 or best.t == 39 then
      G.prompt = "save"
      sfx(SFX.blip)
    elseif best.t == 17 then
      if plr.life < plr.max_life then
        plr.life = plr.max_life
        sfx(SFX.chest)
      end
    elseif best.ev > 0 then
      scr_run(best.ev)
    end
  end
end

-- ─── 主更新 ───────────────────────────────────────────────

function plr_update()
  if plr.life <= 0 then return end
  if plr.shock > 0 then plr.shock = plr.shock - 1 end
  if plr.xp_timer > 0 then plr.xp_timer = plr.xp_timer - 1 end

  local locked = scr_locks_player() or G.prompt or G.dead_t > 0
  local left, right, up, down = false, false, false, false
  local jump_p, shoot_p = false, false
  if not locked then
    left = dir("left")
    right = dir("right")
    up = dir("up")
    down = dir("down")
    jump_p = btnp("a") or btnp("x")
    shoot_p = btnp("b") or btnp("y")
  end
  plr.up = up
  plr.down = down

  if jump_p and plr.on_ground then
    plr.vy = -P.jump
    sfx(SFX.jump)
  end

  -- 水平加速 / 摩擦
  if left and not right then
    plr.dir = -1
    plr.vx = plr.vx - (plr.on_ground and P.dash_ground or P.dash_air)
    plr.vx = math.max(plr.vx, -P.max_move)
  elseif right and not left then
    plr.dir = 1
    plr.vx = plr.vx + (plr.on_ground and P.dash_ground or P.dash_air)
    plr.vx = math.min(plr.vx, P.max_move)
  elseif plr.on_ground then
    if plr.vx < 0 then
      plr.vx = math.min(plr.vx + P.resist, 0)
    else
      plr.vx = math.max(plr.vx - P.resist, 0)
    end
  end
  -- 地面走速上限 max_dash，空中保留惯性上限 max_move（原版 air_physics 语义）
  if plr.on_ground then
    plr.vx = mid(-P.max_dash, plr.vx, P.max_dash)
  else
    plr.vx = mid(-P.max_move, plr.vx, P.max_move)
  end

  -- 重力（上升按住跳 = 低重力）
  if plr.vy < 0 and (btn("a") or btn("x")) and not locked then
    plr.vy = plr.vy + P.gravity_air
  else
    plr.vy = plr.vy + P.gravity_ground
  end
  plr.vy = mid(-P.max_move, plr.vy, P.max_move)

  local l, t, r, b = PLR_HIT.l * SUB, PLR_HIT.t * SUB, PLR_HIT.r * SUB, PLR_HIT.b * SUB
  plr.x = plr.x + plr.vx
  collide_x(plr, l, r, t, b)
  plr.y = plr.y + plr.vy
  collide_y(plr, l, r, t, b)
  if plr.vy >= 0 then
    slope_at(plr, l, r, t, b)
  else
    ceil_slope(plr, l, r, t, b)
  end

  -- 行走动画
  if plr.on_ground and plr.vx ~= 0 then
    plr.anim = plr.anim + 1
  else
    plr.anim = 0
  end

  if shoot_p then shoot() end
  -- 交互：按住 ↑ 亦可触发；触发一次后需松开 ↑ 才重新武装（原版 interacted 标记语义）
  if G.interact_cd > 0 then
    G.interact_cd = G.interact_cd - 1
  elseif dir("up") and not locked then
    if not G.interact_latch then
      try_interact()
    end
  else
    G.interact_latch = false
  end
end

-- 绘制：MyChar 块内 16×16 帧，行 0=左 1=右
function plr_draw()
  if plr.life <= 0 then return end
  if plr.shock > 0 and sar(G.frame, 2) % 2 == 0 then return end -- 受击闪烁
  local row = plr.dir < 0 and 0 or 16
  local col
  if plr.on_ground and plr.vx == 0 then
    col = plr.up and 3 or 0
  elseif not plr.on_ground then
    col = plr.vy < 0 and 2 or 1
  else
    col = WALK_CYCLE[((plr.anim // 5) % 4) + 1]
    if plr.up then col = (col == 0) and 3 or col end
  end
  local a = CS.atlas.mychar[1]
  local sx = sar(plr.x, 9) - G.camx
  local sy = sar(plr.y, 9) - G.camy
  sspr(a[1] + col, a[2] + row, 16, 16, sx - 8, sy - 8)
end

-- ════════ 40_npc.lua ════════
-- 40_npc.lua —— 实体管理：布点生成、地图碰撞、AI、掉落与拾取

npcs = {}
bullets = {}
carets = {}

local SHOOTABLE = { [64] = true, [65] = true, [78] = true }

function npc_spawn_smoke(x, y)
  npcs[#npcs + 1] = {
    t = 4, x = x, y = y, vx = 0, vy = 0, ev = 0, fl = 0,
    anim = math.floor(rnd(4)) // 1, life = 1, dmg = 0, shock = 0, a = 0, on_ground = false,
  }
end

function npc_spawn_crystal(x, y, exp)
  local vx = math.floor(rnd(-0x200, 0x200)) // 1
  local vy = -math.floor(rnd(0, 0x400)) // 1
  npcs[#npcs + 1] = {
    t = 1, x = x, y = y, vx = vx, vy = vy, ev = 0, fl = 0,
    exp = exp, anim = math.floor(rnd(4)) // 1, life = 1, dmg = 0, shock = 0,
    a = 0, bounces = 0, on_ground = false, dir = 1,
  }
end

local function spawn_from_data()
  npcs = {}
  local list = CS.spawns[G.stage] or {}
  for i = 1, #list do
    local d = list[i]
    local ok = true
    if d.t == 15 then ok = not flget(d.fl)          -- 关闭的宝箱：开启后消失
    elseif d.t == 21 then ok = flget(d.fl)          -- 开启的宝箱：开启后出现
    end
    if ok then
      local st = CS.stats[d.t]
      local mo = MAPD[G.stage]
      npcs[#npcs + 1] = {
        t = d.t, ev = d.ev, fl = d.fl, bf = d.bf,
        x = ((mo[1] + d.x) * 16 + 8) * SUB, y = ((mo[2] + d.y) * 16 + 8) * SUB,
        vx = 0, vy = 0, dir = bit32.band(d.bf, 0x1000) ~= 0 and 1 or -1,
        life = st and st.life or 1, dmg = st and st.dmg or 0,
        invul = st and st.invul or false,
        shock = 0, anim = 0, a = 0, b = 0, on_ground = false,
      }
    end
  end
end

function npc_change_event(ev, typ)
  for i = 1, #npcs do
    if npcs[i].ev == ev then
      local st = CS.stats[typ]
      npcs[i].t = typ
      npcs[i].life = st and st.life or 1
      npcs[i].dmg = st and st.dmg or 0
      npcs[i].invul = st and st.invul or false
    end
  end
end

function npc_delete_event(ev)
  for i = #npcs, 1, -1 do
    if npcs[i].ev == ev then
      deli(npcs, i)
    end
  end
end

-- ─── 地图碰撞（与玩家同一套语义）─────────────────────────

local function cell_solid(cx, cy)
  local t = mget(cx, cy)
  return fget(t, 0)
end

local function npc_bounds(n)
  local st = CS.stats[n.t]
  local hb = st and st.hb or { 4, 4, 4, 4 }
  return hb[1] * SUB, hb[2] * SUB, hb[3] * SUB, hb[4] * SUB
end

local function collide_x(n, l, r, t, b)
  if n.vx > 0 then
    local cx = sar(n.x + r, 13)
    if cell_solid(cx, sar(n.y - t + 256, 13)) or cell_solid(cx, sar(n.y + b - 256, 13)) then
      n.x = lsl(cx, 13) - r
      n.vx = 0
      n.wall = 1
    end
  elseif n.vx < 0 then
    local cx = sar(n.x - l, 13)
    if cell_solid(cx, sar(n.y - t + 256, 13)) or cell_solid(cx, sar(n.y + b - 256, 13)) then
      n.x = lsl(cx + 1, 13) + l
      n.vx = 0
      n.wall = -1
    end
  end
end

local function collide_y(n, l, r, t, b)
  n.on_ground = false
  if n.vy > 0 then
    local cy = sar(n.y + b, 13)
    if cell_solid(sar(n.x - l + 256, 13), cy) or cell_solid(sar(n.x + r - 256, 13), cy) then
      n.y = lsl(cy, 13) - b
      n.vy = 0
      n.on_ground = true
    end
  elseif n.vy < 0 then
    local cy = sar(n.y - t, 13)
    if cell_solid(sar(n.x - l + 256, 13), cy) or cell_solid(sar(n.x + r - 256, 13), cy) then
      n.y = lsl(cy + 1, 13) + t
      n.vy = 0
    end
  end
end

-- ─── 掉落 / 死亡 ──────────────────────────────────────────

local function npc_die(n)
  local st = CS.stats[n.t]
  sfx(SFX.die)
  for i = 1, 3 do
    npc_spawn_smoke(n.x + math.floor(rnd(-6, 6)) * SUB, n.y + math.floor(rnd(-4, 4)) * SUB)
  end
  if st and st.exp > 0 then
    npc_spawn_crystal(n.x, n.y, st.exp)
  end
end

local function bullet_hits_npc(b)
  local br = 2 * SUB -- 子弹近似半径
  for i = 1, #npcs do
    local n = npcs[i]
    if SHOOTABLE[n.t] and not n.invul and n.shock <= 0 then
      local l, t, r, bo = npc_bounds(n)
      if math.abs(b.x - n.x) < br + l + r and math.abs(b.y - n.y) < br + t + bo then
        n.life = n.life - b.dmg
        n.shock = 30
        sfx(SFX.hit)
        caret_spawn(b.x, b.y, "diss", 0)
        if n.life <= 0 then
          npc_die(n)
          if n.t == 78 and n.ev > 0 then
            scr_run(n.ev)
          end
          deli(npcs, i)
        end
        return true
      end
    end
  end
  return false
end

-- ─── 各类型 AI ───────────────────────────────────────────

local function ai_critter(n)
  local dx = plr.x - n.x
  local dy = plr.y - n.y
  if n.a == 1 then
    if n.b < 8 then n.b = n.b + 1 end
    n.anim = 0
    if n.b >= 8 and math.abs(dx) < 0xe000 and math.abs(dy) < 0xa000 then
      n.anim = 1
    end
    if n.b >= 8 and math.abs(dx) < 0x8000 and dy > -0xa000 and dy < 0x6000 then
      n.a = 2
      n.b = 0
      n.anim = 0
    end
  elseif n.a == 2 then
    n.b = n.b + 1
    if n.b > 8 then
      n.a = 3
      n.anim = 2
      n.dir = dx < 0 and -1 or 1
      n.vx = n.dir * 0x100
      n.vy = -0x5ff
      sfx(SFX.critter)
    end
  elseif n.a == 3 then
    if n.on_ground and n.vy == 0 then
      n.vx = 0
      n.anim = 0
      n.b = 0
      n.a = 1
      sfx(SFX.thud)
    end
  end
  n.vy = math.min(n.vy + 0x40, 0x5ff)
  local l, t, r, bo = npc_bounds(n)
  n.x = n.x + n.vx
  collide_x(n, l, r, t, bo)
  n.y = n.y + n.vy
  collide_y(n, l, r, t, bo)
  if n.on_ground and n.vy >= 0 then
    slope_at_npc(n, l, r, t, bo)
  end
end

local function ai_bat(n)
  if n.a <= 1 then
    if n.a == 0 then
      n.a = 1
      n.b = math.floor(rnd(50)) // 1
    end
    n.b = n.b + 1
    if n.b >= 50 then
      n.a = 2
      n.b = 0
      n.vy = 0x300
    end
  elseif n.a == 2 then
    local dx = plr.x - n.x
    n.dir = dx < 0 and -1 or 1
    n.vx = n.dir * 0x100
    local dyt = plr.y - 0x1800 - n.y
    n.vy = n.vy + mid(-0x10, dyt // 16, 0x10)
    n.vy = mid(-0x300, n.vy, 0x300)
  end
  local l, t, r, bo = npc_bounds(n)
  n.x = n.x + n.vx
  collide_x(n, l, r, t, bo)
  n.y = n.y + n.vy
  collide_y(n, l, r, t, bo)
  n.anim = (n.anim + 1) % 3
end

local function ai_crystal(n)
  if n.a == 0 then
    n.a = 1
    n.anim = math.floor(rnd(4)) // 1
  end
  n.vy = math.min(n.vy + 0x2a, 0x5ff)
  local l, t, r, bo = 2 * SUB, 2 * SUB, 2 * SUB, 2 * SUB
  n.x = n.x + n.vx
  if n.vx < 0 and cell_solid(sar(n.x - l, 13), sar(n.y, 13)) then
    n.x = (sar(n.x - l, 13) + 1) * TILE + l
    n.vx = -n.vx
  elseif n.vx > 0 and cell_solid(sar(n.x + r, 13), sar(n.y, 13)) then
    n.x = sar(n.x + r, 13) * TILE - r
    n.vx = -n.vx
  end
  n.y = n.y + n.vy
  if n.vy > 0 and cell_solid(sar(n.x, 13), sar(n.y + bo, 13)) then
    n.y = sar(n.y + bo, 13) * TILE - bo
    sfx(SFX.bounce)
    n.vy = -0x280
    n.vx = n.vx * 2 // 3
    n.bounces = n.bounces + 1
  elseif n.vy < 0 and cell_solid(sar(n.x, 13), sar(n.y - t, 13)) then
    n.y = (sar(n.y - t, 13) + 1) * TILE + t
    n.vy = 0
  end
  if n.bounces > 2 then
    n.vy = n.vy - 0x100
  end
  n.anim = (n.anim + (n.dir > 0 and 1 or -1)) % 6
  -- 拾取
  if math.abs(plr.x - n.x) < 0xa00 + 4 * SUB and math.abs(plr.y - n.y) < 0xa00 + 6 * SUB then
    if plr.weapon then
      add_xp_pub(n.exp)
    end
    sfx(SFX.xp)
    deli(npcs, table_find_npc(n))
  end
end

local function ai_smoke(n)
  n.a = n.a + 1
  if n.a > 24 then
    del(npcs, n)
  end
end

local STATIC_TYPES = {
  [0] = true, [15] = true, [16] = true, [17] = true, [18] = true, [21] = true,
  [37] = true, [39] = true, [211] = true,
}
local VILLAGER = { [30] = true, [42] = true, [60] = true, [61] = true, [74] = true, [79] = true }

function npcs_update()
  for i = #npcs, 1, -1 do
    local n = npcs[i]
    if n.shock > 0 then n.shock = n.shock - 1 end
    if n.t == 64 then
      ai_critter(n)
    elseif n.t == 65 then
      ai_bat(n)
    elseif n.t == 1 then
      ai_crystal(n)
    elseif n.t == 4 then
      ai_smoke(n)
    end
    -- 接触伤害
    if n.dmg > 0 and plr.life > 0 and plr.shock <= 0 and G.dead_t <= 0 then
      local pl, pt, pr, pb = PLR_HIT.l * SUB, PLR_HIT.t * SUB, PLR_HIT.r * SUB, PLR_HIT.b * SUB
      local l, t, r, bo = npc_bounds(n)
      if math.abs(n.x - plr.x) < l + r and math.abs(n.y - plr.y) < t + pb then
        plr_damage(n.dmg)
      end
    end
  end
end

-- ─── 子弹 ────────────────────────────────────────────────

function bullet_spawn(x, y, dir, lvl)
  local spec = WEAPON.bullets[lvl]
  local b = {
    x = x, y = y, lvl = lvl, dmg = spec.dmg, life_t = spec.life_t,
    vx = 0, vy = 0,
  }
  if dir == "left" then b.vx = -WEAPON.speed
  elseif dir == "right" then b.vx = WEAPON.speed
  elseif dir == "up" then b.vy = -WEAPON.speed
  else b.vy = WEAPON.speed
  end
  bullets[#bullets + 1] = b
end

function bullet_count_player()
  return #bullets
end

function bullets_update()
  for i = #bullets, 1, -1 do
    local b = bullets[i]
    b.x = b.x + b.vx
    b.y = b.y + b.vy
    b.life_t = b.life_t - 1
    local dead = b.life_t <= 0
    if not dead then
      local cx, cy = sar(b.x, 13), sar(b.y, 13)
      if fget(mget(cx, cy), 0) then
        dead = true
        caret_spawn(b.x, b.y, "diss", 0)
      end
    end
    if not dead and bullet_hits_npc(b) then
      dead = true
    end
    if dead then
      deli(bullets, i)
    end
  end
end

function bullet_hits_npc_pub(b)
  return bullet_hits_npc(b)
end

-- ─── 特效 ────────────────────────────────────────────────

function caret_spawn(x, y, kind, dir)
  carets[#carets + 1] = { x = x, y = y, kind = kind, dir = dir, a = 0 }
end

function carets_update()
  for i = #carets, 1, -1 do
    local c = carets[i]
    c.a = c.a + 1
    local max = c.kind == "shoot" and 12 or (c.kind == "diss" and 8 or 80)
    if c.kind == "level" and c.a < 20 then
      c.y = c.y - SUB
    end
    if c.a > max then
      deli(carets, i)
    end
  end
end

-- 公共入口（player 层用）
function add_xp_pub(n)
  local w = plr.weapon
  if not w then return end
  w.exp = w.exp + n
  local lt = WEAPON.level_table
  if w.level < 3 and w.exp >= lt[w.level] then
    w.level = w.level + 1
    w.exp = 0
    sfx(SFX.levelup)
    caret_spawn(plr.x, plr.y - 10 * SUB, "level", 0)
  elseif w.level >= 3 and w.exp >= lt[3] then
    w.exp = lt[3]
  end
  plr.xp_timer = 30
end

function table_find_npc(n)
  for i = 1, #npcs do
    if npcs[i] == n then return i end
  end
  return #npcs
end

-- 斜坡（NPC 版：仅地板坡）
function slope_at_npc(n, l, r, t, b)
  local cx = sar(n.x, 13)
  local cy = sar(n.y + b, 13)
  local t0 = mget(cx, cy)
  local code = bit32.bor(fget(t0, 1) and 1 or 0, fget(t0, 2) and 2 or 0, fget(t0, 3) and 4 or 0)
  if code < 5 then return end
  local dx = n.x - lsl(cx, 13)
  local ty0 = lsl(cy, 13)
  local Q = 0x800
  local line
  if code == 5 then line = ty0 + dx // 2 - Q
  elseif code == 6 then line = ty0 + dx // 2 + Q
  elseif code == 7 then line = ty0 - dx // 2 + Q
  elseif code == 8 then line = ty0 - dx // 2 - Q
  end
  if line and n.y + b > line then
    n.y = line - b
    if n.vy > 0 then n.vy = 0 end
    n.on_ground = true
  end
end

function npcs_spawn_for_stage()
  spawn_from_data()
  bullets = {}
  carets = {}
end

-- ════════ 50_game.lua ════════
-- 50_game.lua —— 全局状态、关卡切换、相机、HUD、对话框、存档

G = {
  stage = 13,
  camx = 0, camy = 0,
  lookx = 0, looky = 0,
  fade = 0, fade_tgt = 0,
  frame = 0,
  dead_t = 0,
  prompt = nil,        -- "save"
  interact_cd = 0,
  interact_latch = false,
  items = {},
  title_t = 0,
}

function stage_switch(s, ev, tx, ty)
  G.stage = s
  npcs_spawn_for_stage()
  if tx then
    local mo = MAPD[s]
    plr.x = ((mo[1] + tx) * 16 + 8) * SUB
    plr.y = ((mo[2] + ty) * 16 + 8) * SUB
  end
  plr.vx, plr.vy = 0, 0
  update_camera(true)
  G.fade_tgt = 0
  if ev then
    scr_run(ev)
  end
end

function update_camera(snap)
  local d = MAPD[G.stage]
  local dims = CS.dims[G.stage]
  local wx, wy = d[1] * 16, d[2] * 16
  local ww, wh = dims[1] * 16, dims[2] * 16
  -- 视线前探
  local tx = 0
  if plr.vx > 0x100 then tx = 16 elseif plr.vx < -0x100 then tx = -16 end
  local ty = 0
  if plr.up then ty = -16 elseif plr.down and plr.on_ground then ty = 16 end
  if snap then G.lookx, G.looky = tx, ty
  else
    if G.lookx < tx then G.lookx = math.min(G.lookx + 1, tx) else G.lookx = math.max(G.lookx - 1, tx) end
    if G.looky < ty then G.looky = math.min(G.looky + 1, ty) else G.looky = math.max(G.looky - 1, ty) end
  end
  local cx = mid(wx, sar(plr.x, 9) - 128 + G.lookx, wx + ww - 256)
  local cy = mid(wy, sar(plr.y, 9) - 128 + G.looky, wy + wh - 256)
  if ww <= 256 then cx = wx + (ww - 256) // 2 end
  if wh <= 256 then cy = wy end
  G.camx, G.camy = cx, cy
end

-- ─── 存档 ─────────────────────────────────────────────────

-- 结构（SPEC §13）：{stage, x, y（像素）, max_life, life, weapon_level, weapon_exp, dir, flags}
function do_save()
  save({
    stage = G.stage,
    x = plr.x // 512,
    y = plr.y // 512,
    max_life = plr.max_life,
    life = plr.life,
    weapon_level = plr.weapon and plr.weapon.level or 0,
    weapon_exp = plr.weapon and plr.weapon.exp or 0,
    dir = plr.dir,
    flags = flsave(),
  })
end

-- 读出存档表；无存档或损坏返回 nil
local function save_data()
  local d = load()
  return type(d) == "table" and d or nil
end

-- 缺失或非数字字段按 0 处理
local function save_num(d, k)
  local v = d[k]
  return type(v) == "number" and v or 0
end

function has_save()
  local d = save_data()
  return d ~= nil and save_num(d, "stage") > 0
end

function load_save()
  local d = save_data() or {}
  if not plr then plr = new_player(0, 0, 1) end
  plr.max_life = save_num(d, "max_life")
  plr.life = save_num(d, "life")
  plr.dir = save_num(d, "dir") ~= 0 and save_num(d, "dir") or 1
  if save_num(d, "weapon_level") > 0 then
    plr.weapon = { id = 2, level = save_num(d, "weapon_level"), exp = save_num(d, "weapon_exp") }
  end
  flload(d.flags)
  G.items[2] = flget(322)
  G.stage = save_num(d, "stage")
  npcs_spawn_for_stage()
  plr.x = save_num(d, "x") * 512
  plr.y = save_num(d, "y") * 512
  plr.vx, plr.vy = 0, 0
  update_camera(true)
  G.fade_tgt = 0
end

-- ─── 每帧推进 ─────────────────────────────────────────────

function game_update()
  G.frame = G.frame + 1
  -- 淡出推进
  if G.fade < G.fade_tgt then
    G.fade = math.min(G.fade + 0.25, G.fade_tgt)
  elseif G.fade > G.fade_tgt then
    G.fade = math.max(G.fade - 0.25, G.fade_tgt)
  end

  scr_update()

  if G.dead_t > 0 then
    G.dead_t = G.dead_t - 1
    if G.dead_t == 40 then
      G.fade_tgt = 4
    elseif G.dead_t == 1 then
      if has_save() then
        load_save()
      else
        new_game()
      end
      G.fade_tgt = 0
    end
    carets_update()
    return
  end

  plr_update()
  npcs_update()
  bullets_update()
  carets_update()
  update_camera(false)

  -- 存档确认
  if G.prompt == "save" then
    if btnp("a") then
      do_save()
      sfx(SFX.save)
      G.prompt = nil
    elseif btnp("b") then
      G.prompt = nil
    end
  end
end

-- ─── 绘制 ─────────────────────────────────────────────────

local NPC_FRAME = {
  [16] = function(n) return (sar(G.frame, 3) % 8) + 1 end,
  [64] = function(n) return n.anim + (n.dir < 0 and 1 or 4) end,
  [65] = function(n) return n.anim + (n.dir > 0 and 5 or 1) end,
  [1] = function(n) return n.anim + 1 end,
  [4] = function(n) return (sar(n.a, 2) % 4) + 1 end,
  [211] = function(n) return (sar(n.x, 13) + sar(n.y, 13)) % 4 + 1 end,
}

local function draw_npcs()
  for i = 1, #npcs do
    local n = npcs[i]
    local rects = CS.atlas["npc" .. n.t]
    if rects then
      local idx = 1
      if NPC_FRAME[n.t] then
        idx = NPC_FRAME[n.t](n)
        idx = mid(1, idx, #rects)
      end
      local r = rects[idx]
      local sx = sar(n.x, 9) - G.camx - sar(r[3], 1)
      local sy = sar(n.y, 9) - G.camy - sar(r[4], 1)
      if n.t == 18 then sy = sy - 4 end
      sspr(r[1], r[2], r[3], r[4], sx, sy)
    end
  end
end

local function draw_bullets()
  for i = 1, #bullets do
    local b = bullets[i]
    local key = "b" .. (3 + b.lvl) .. ((b.vx ~= 0) and "h" or "v")
    local r = CS.atlas[key][1]
    sspr(r[1], r[2], r[3], r[4], sar(b.x, 9) - G.camx - 8, sar(b.y, 9) - G.camy - 8)
  end
end

local function draw_carets()
  for i = 1, #carets do
    local c = carets[i]
    if c.kind == "shoot" then
      local r = CS.atlas.caret_shoot[(sar(c.a, 2) % 4) + 1]
      local ox = c.dir < 0 and -12 or 4
      sspr(r[1], r[2], r[3], r[4], sar(c.x, 9) - G.camx - 8 + (c.vy ~= 0 and 0 or ox), sar(c.y, 9) - G.camy - 8)
    elseif c.kind == "diss" then
      local r = CS.atlas.caret_diss[(sar(c.a, 1) % 4) + 1]
      sspr(r[1], r[2], r[3], r[4], sar(c.x, 9) - G.camx - 4, sar(c.y, 9) - G.camy - 4)
    elseif c.kind == "level" and c.a < 80 then
      local r = CS.atlas.caret_level[(sar(c.a, 3) % 2) + 1]
      sspr(r[1], r[2], r[3], r[4], sar(c.x, 9) - G.camx - 28, sar(c.y, 9) - G.camy - 24)
    end
  end
end

local function draw_map_layer()
  if CS.bg.bkblue ~= nil and G.stage == 11 then
    -- 咪咪村：bkBlue 平铺背景（自由区 0 起，64KB=256×256 索引）
    memcpy(0x0B0000, 0x0C63A0, 65536)
  else
    cls(CS.bg.bk0_color or 0)
  end
  local tx, ty = sar(G.camx, 4), sar(G.camy, 4)
  map(tx, ty, -(G.camx % 16), -(G.camy % 16), 17, 17, 0)
end

local function draw_msg()
  local m = scr.msg
  if not m then return end
  rectfill(6, 192, 244, 58, 0)
  rect(6, 192, 244, 58, 7)
  local y = 200
  local shown = m.chars
  for i = 1, #m.lines do
    local ln = m.lines[i]
    local take = mid(0, shown, #ln)
    if take > 0 then
      printw(ln:sub(1, take), 16, y, 7, 224)
    end
    shown = shown - #ln
    y = y + 12
    if shown <= 0 then break end
  end
  -- 等键闪烁箭头
  if scr.wait_key and sar(G.frame, 4) % 2 == 0 then
    print("▼", 236, 234, 7)
  end
end

local function draw_hud()
  -- 生命
  rect(5, 5, 52, 9, 7)
  rectfill(6, 6, 50, 7, 0)
  rectfill(6, 6, 50 * plr.life // plr.max_life, 7, 58)
  -- 武器等级
  if plr.weapon then
    print("Lv." .. plr.weapon.level, 6, 16, 7)
    local wexp = plr.weapon.exp
    local cap = plr.weapon.level >= 3 and WEAPON.level_table[3] or WEAPON.level_table[plr.weapon.level]
    rectfill(6, 26, 20 * math.min(1, wexp / cap), 2, 10)
  end
end

function game_draw()
  draw_map_layer()
  draw_npcs()
  plr_draw()
  draw_bullets()
  draw_carets()
  draw_hud()
  draw_msg()
  if G.prompt == "save" then
    rectfill(48, 92, 160, 56, 0)
    rect(48, 92, 160, 56, 7)
    printw("要在此记录吗？", 64, 102, 7, 128)
    print(btnicon("a") .. " 记录", 64, 124, 6)
    print(btnicon("b") .. " 取消", 150, 124, 6)
  end
  -- 淡出覆盖
  if G.fade > 0 then
    apply_fade(G.fade)
  end
  if G.fade >= 4 then
    rectfill(0, 0, 256, 256, 0)
    apply_fade(0)
  end
end

